#!/usr/bin/env python3
"""Inspect unpacked quarterly_report.docx to identify headline paragraphs."""
import os
import xml.dom.minidom as minidom

DOC = os.path.join("unpacked_quarterly_report", "word", "document.xml")

def text_of_para(p):
    parts = []
    for node in p.getElementsByTagName("w:t"):
        if node.firstChild:
            parts.append(node.data if node.firstChild is None else "".join(
                c.data for c in node.childNodes if c.nodeType == c.TEXT_NODE))
    return "".join(parts)

def style_of_para(p):
    pPr = p.getElementsByTagName("w:pPr")
    if not pPr:
        return None
    styles = pPr[0].getElementsByTagName("w:pStyle")
    if not styles:
        return None
    return styles[0].getAttribute("w:val")

dom = minidom.parse(DOC)
paras = dom.getElementsByTagName("w:p")
print("total paragraphs:", len(paras))
for i, p in enumerate(paras):
    style = style_of_para(p)
    txt = text_of_para(p).strip()
    if style is not None and txt:
        print(f"[{i}] style={style!r} text={txt[:100]!r}")

