import re
import html

PATH = 'unpacked/word/document.xml'

with open(PATH, 'r', encoding='ascii') as fh:
    xml = fh.read()

def is_headline(text):
    un = html.unescape(text).strip()
    if len(un) < 4 or not un:
        return False
    if un[0] in '\u2022\u2500':  # bullet or box-drawing separator
        return False
    letters = [c for c in un if c.isalpha()]
    if not letters:
        return False
    return all(c.isupper() for c in letters)

run_re = re.compile(r'(<w:r>\s*<w:rPr>)(.*?)(</w:rPr>\s*<w:t xml:space="preserve">)(.*?)(</w:t>)', re.S)

count = 0

def repl(m):
    global count
    inner, text = m.group(2), m.group(4)
    if not is_headline(text):
        return m.group(0)
    if '<w:u w:val="single"/>' in inner:
        return m.group(0)
    count += 1
    return m.group(1) + inner + '<w:u w:val="single"/>' + m.group(3) + text + m.group(5)

new_xml, n = run_re.subn(repl, xml)
assert count == n and n > 0, (count, n)

with open(PATH, 'w', encoding='ascii') as fh:
    fh.write(new_xml)

print('underlined headline runs:', n)

"""Underline all headlines in unpacked/word/document.xml (quarterly_report.docx)."""
import xml.dom.minidom as minidom

PATH = "unpacked/word/document.xml"

# Headline paragraphs identified from the report: all-caps section titles.
HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

dom = minidom.parse(PATH)

def local(el):
    return el.tagName.split(":")[-1] if el.tagName else ""

def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None:
            parts.append(t.firstChild.nodeValue)
    return "".join(parts)

def ensure_underline(rpr):
    for u in rpr.getElementsByTagName("w:u"):
        if u.getAttribute("w:val") == "single":
            return False  # already underlined
    u = dom.createElementNS(W, "w:u")
    u.setAttribute("w:val", "single")
    # Schema order: <w:u> comes after szCs/highlight; append is valid here
    # (rPr children are rFonts, sz, szCs in these runs).
    rpr.appendChild(u)
    return True

changed = []
for p in dom.getElementsByTagName("w:p"):
    text = para_text(p).strip()
    if text in HEADLINES:
        added = False
        for r in p.getElementsByTagName("w:r"):
            rpr = r.getElementsByTagName("w:rPr")
            if rpr:
                added = ensure_underline(rpr[0]) or added
        changed.append((text, added))

with open(PATH, "wb") as fh:
    dom.writexml(fh, encoding="ascii")

for text, added in changed:
    print(("UNDERLINED " if added else "ALREADY-UNDERLINED ") + text)
print("TOTAL HEADLINES:", len(changed))
missing = HEADLINES - {t for t, _ in changed}
print("MISSING:", sorted(missing) if missing else "none")

